fx.Annotate(
				func(cfg config, httpClient *client.HTTPClient) *filterservice.FilterServiceClient {
					return filterservice.NewClient(httpClient, cfg.FilterServiceURL)
				},
				fx.As(new(service.WheelCodeFetcher)),
			)

fx.Invoke(
				runMigrations,
				func(shutdowner fx.Shutdowner, logger *loggingsdk.Logger) {
					err := shutdowner.Shutdown()
					if err != nil {
						logger.Error(context.Background(), "Shutdown failed", err)
					}
				},
			)

fx.New(
			fx.Options(opts...),
			fx.Provide(
				newBinderConfig,
				newMigratorConfig,
				newMigratorSentryConfig,
				newSentryClient,
				newMigratorLogger,
				newDBMigratorConfig,
				postgres.NewMigrator,
			),
			fx.WithLogger(loggingsdk.NewFxEventLogger),
			fx.Invoke(
				runMigrations,
				func(shutdowner fx.Shutdowner, logger *loggingsdk.Logger) {
					err := shutdowner.Shutdown()
					if err != nil {
						logger.Error(context.Background(), "Shutdown failed", err)
					}
				},
			),
		)
